void main() {
  const zaiUrl = 'https://api.z.ai/api/coding/paas/v4';
  const openRouterUrl = 'https://openrouter.ai/api/v1';
  const zaiKeyName = 'FA_KEY_API_Z_AI';

  Model modelOf(String baseUrl) => Model(
    id: 'glm-5.3-flash',
    api: 'openai-completions',
    provider: 'openai',
