            provider: record.provider,
            modelId: record.model,
            baseUrl: model?.baseUrl,
            customProvider: model?.customProvider,
          );
        case ActiveToolsChangeRecord record:
          activeToolNames = [...record.activeToolNames];
        default:
      }
    }
