        // The endpoint the binding believes (z.ai): the diagnosis must
        // follow the ATTEMPTED provider (copilot), not this binding.
        final line = renderer.errorLine(copilotExchangeFailure, zaiUrl);

        expect(line, contains('copilot'));
        expect(
