      final legacy = names
          .where((name) => (envVarValue?.call(name) ?? '').isNotEmpty)
          .firstOrNull;
      if (legacy != null) return storeHintMessage(legacy, baseUrl);
    }
    return noKeyHint(entryKey, baseUrl, spec, scopedName, names);

