          store: FakeSecureKeyStore()..map[zaiKeyName] = 'sk-zai',
          providerKind: 'copilot',
          activeCustomName: null,
        );

        expect(renderer.errorLine(zaiFailure, zaiUrl), contains(zaiKeyName));
      },
    );
