      expect(renderer.keyStatusLine(modelOf(zaiUrl)), 'key: $zaiKeyName');
    });

    test('the default endpoint still resolves the catalog env key', () async {
      final renderer = await rendererOf(
        env: const {'OPENROUTER_API_KEY': 'sk-openrouter'},
